CREATE OR REPLACE FUNCTION public.approve_product_alias_atomic(p_proposal_id uuid, p_reviewer_id text, p_reviewer_role text, p_reason text, p_signature_verified boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_proposal record;
  v_product record;
  v_existing_alias record;
  v_now timestamptz := clock_timestamp();
BEGIN
  -- 1. Authorization check: signature verification and role required
  IF NOT p_signature_verified THEN
    RAISE EXCEPTION 'AUTHORIZATION_FAILED: Cryptographic server signature verification is required.';
  END IF;

  IF p_reviewer_role NOT IN ('catalog_admin', 'catalog_operator') THEN
    RAISE EXCEPTION 'AUTHORIZATION_FAILED: Role % is not authorized to approve aliases.', p_reviewer_role;
  END IF;

  -- 2. Lock proposal row for update
  SELECT * INTO v_proposal
  FROM public.product_alias_proposals
  WHERE id = p_proposal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROPOSAL_NOT_FOUND: Proposal ID % does not exist.', p_proposal_id;
  END IF;

  IF v_proposal.status NOT IN ('pending_review', 'conflict_needs_review') THEN
    RAISE EXCEPTION 'INVALID_PROPOSAL_STATE: Proposal is already in % state.', v_proposal.status;
  END IF;

  -- 3. Verify target product still exists and is verified
  SELECT * INTO v_product
  FROM public.products
  WHERE id = v_proposal.proposed_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_PRODUCT_NOT_FOUND: Product ID % does not exist.', v_proposal.proposed_product_id;
  END IF;

  IF v_product.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'TARGET_PRODUCT_NOT_VERIFIED: Product ID % is % (must be verified).',
      v_proposal.proposed_product_id, v_product.verification_status;
  END IF;

  -- 4. Conflict check against existing active aliases in product_aliases
  SELECT * INTO v_existing_alias
  FROM public.product_aliases
  WHERE public.normalize_alias_key(alias_text) = v_proposal.canonical_normalized_key
  LIMIT 1;

  IF FOUND THEN
    IF v_existing_alias.product_id = v_proposal.proposed_product_id THEN
      RAISE EXCEPTION 'DUPLICATE_SAME_PRODUCT_ALIAS: Normalized key already exists for this product.';
    ELSE
      RAISE EXCEPTION 'CROSS_PRODUCT_ALIAS_CONFLICT: Normalized key conflicts with product ID %.', v_existing_alias.product_id;
    END IF;
  END IF;

  -- 5. Insert into active product_aliases
  INSERT INTO public.product_aliases (
    product_id,
    alias_text,
    language,
    source
  ) VALUES (
    v_proposal.proposed_product_id,
    v_proposal.alias_text,
    v_proposal.language,
    'approved_proposal:' || p_proposal_id::text
  );

  -- 6. Update proposal status
  UPDATE public.product_alias_proposals
  SET
    status = 'approved',
    reviewing_operator_id = p_reviewer_id,
    review_decision = 'approved',
    review_reason = p_reason,
    reviewed_at = v_now,
    updated_at = v_now
  WHERE id = p_proposal_id;

  -- 7. Append immutable audit log entry
  INSERT INTO public.product_alias_audit_log (
    proposal_id,
    action,
    actor_id,
    actor_role,
    previous_status,
    new_status,
    reason,
    signature_verified,
    metadata
  ) VALUES (
    p_proposal_id,
    'approved',
    p_reviewer_id,
    p_reviewer_role,
    v_proposal.status,
    'approved',
    p_reason,
    true,
    jsonb_build_object('canonical_normalized_key', v_proposal.canonical_normalized_key)
  );

  RETURN jsonb_build_object(
    'success', true,
    'proposal_id', p_proposal_id,
    'status', 'approved',
    'approved_at', v_now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.build_sanitized_consumer_contract_v2(p_contract_v2 jsonb, p_approved_product_image_url text DEFAULT NULL::text, p_subject_scope text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_assets jsonb;
  v_clean_card jsonb;
  v_clean_thumb jsonb;
  v_scope text := COALESCE(p_subject_scope, CASE WHEN p_approved_product_image_url IS NOT NULL THEN 'product_package' ELSE 'unverified' END);
BEGIN
  IF p_contract_v2 IS NULL THEN
    RETURN NULL;
  END IF;

  v_assets := p_contract_v2->'assets';

  -- WIFRAN-07G §6.E, WIFRAN-07H §4, WIFRAN-07J §6: Strip all private offer-images crop paths and delivery URLs.
  -- Only populate delivery_url with the approved catalog product image or approved illustrative offer visual.
  v_clean_card := jsonb_build_object(
    'storage_bucket', CASE WHEN p_approved_product_image_url IS NOT NULL THEN 'product-images' ELSE NULL END,
    'storage_object_path', NULL,
    'delivery_url', p_approved_product_image_url,
    'subject_scope', v_scope,
    'upload_state', CASE WHEN p_approved_product_image_url IS NOT NULL THEN 'uploaded' ELSE COALESCE(v_assets->'offer_card'->>'upload_state', 'pending') END
  );

  v_clean_thumb := jsonb_build_object(
    'storage_bucket', CASE WHEN p_approved_product_image_url IS NOT NULL THEN 'product-images' ELSE NULL END,
    'storage_object_path', NULL,
    'delivery_url', p_approved_product_image_url,
    'subject_scope', v_scope,
    'upload_state', CASE WHEN p_approved_product_image_url IS NOT NULL THEN 'uploaded' ELSE COALESCE(v_assets->'product_thumbnail'->>'upload_state', 'pending') END
  );

  DECLARE
    v_assessments jsonb := COALESCE(p_contract_v2->'assessments', '{}'::jsonb);
    v_reason_codes jsonb := v_assessments->'reason_codes';
    v_has_image boolean := (p_approved_product_image_url IS NOT NULL);
  BEGIN
    IF v_has_image AND v_reason_codes IS NOT NULL AND jsonb_typeof(v_reason_codes) = 'array' THEN
      v_reason_codes := v_reason_codes - 'MEDIA_UPLOAD_PENDING';
      v_assessments := jsonb_set(v_assessments, '{reason_codes}', v_reason_codes);
    END IF;

    RETURN jsonb_build_object(
      'record_metadata', p_contract_v2->'record_metadata',
      'product_facts', p_contract_v2->'product_facts',
      'assortment', p_contract_v2->'assortment',
      'quantity_semantics', p_contract_v2->'quantity_semantics',
      'price_terms', p_contract_v2->'price_terms',
      'promotion_terms', p_contract_v2->'promotion_terms',
      'eligibility', p_contract_v2->'eligibility',
      'assessments', v_assessments,
      'assets', jsonb_build_object(
        'offer_card', v_clean_card,
        'product_thumbnail', v_clean_thumb
      )
    );
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_indirect_publication_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_op_id_text text;
  v_op_id uuid;
  v_suppress text;
  v_seq integer;
  v_pk text;
  v_pre jsonb;
  v_post jsonb;
  v_mut_type text;
BEGIN
  v_suppress := current_setting('wifran.suppress_journal_trigger', true);
  IF v_suppress = 'true' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_op_id_text := current_setting('wifran.active_publish_operation_id', true);
  IF v_op_id_text IS NULL OR length(trim(v_op_id_text)) = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  BEGIN
    v_op_id := v_op_id_text::uuid;
  EXCEPTION WHEN OTHERS THEN
    RETURN COALESCE(NEW, OLD);
  END;

  IF TG_OP = 'INSERT' THEN
    v_mut_type := 'insert';
    v_pre := NULL;
    v_post := to_jsonb(NEW);
    v_pk := COALESCE(v_post->>'id', '');
  ELSIF TG_OP = 'UPDATE' THEN
    v_mut_type := 'update';
    v_pre := to_jsonb(OLD);
    v_post := to_jsonb(NEW);
    v_pk := COALESCE(v_post->>'id', v_pre->>'id', '');
  ELSE
    v_mut_type := 'delete';
    v_pre := to_jsonb(OLD);
    v_post := NULL;
    v_pk := COALESCE(v_pre->>'id', '');
  END IF;

  IF length(v_pk) = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT COALESCE(MAX(sequence_no), 0) + 1
  INTO v_seq
  FROM public.publication_journal_mutations
  WHERE publish_operation_id = v_op_id;

  INSERT INTO public.publication_journal_mutations (
    publish_operation_id,
    sequence_no,
    table_schema,
    table_name,
    record_pk,
    mutation_type,
    capture_source,
    pre_state,
    post_state,
    reused_existing,
    metadata
  ) VALUES (
    v_op_id,
    v_seq,
    TG_TABLE_SCHEMA,
    TG_TABLE_NAME,
    v_pk,
    v_mut_type,
    'db_trigger',
    v_pre,
    v_post,
    false,
    jsonb_build_object('trigger_name', TG_NAME)
  );

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_issue_report_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    NEW.user_id := auth.uid();
  ELSE
    NEW.user_id := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_prevent_product_id_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'products.id is immutable and cannot be updated (current: %, attempted: %)', OLD.id, NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_alias_key(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_res text;
BEGIN
  IF p_text IS NULL THEN
    RETURN NULL;
  END IF;

  v_res := trim(lower(p_text));
  -- Strip tatweel / kashida (U+0640)
  v_res := regexp_replace(v_res, 'ـ', '', 'g');
  -- Strip Arabic diacritics / tashkeel (fatha, damma, kasra, sukun, shadda, tanween: U+064B-U+065F, U+0670)
  v_res := regexp_replace(v_res, '[\u064B-\u065F\u0670]', '', 'g');
  -- Normalize Alef with hamza / madda to plain Alef
  v_res := regexp_replace(v_res, '[أإآ]', 'ا', 'g');
  -- Normalize Alef Maksura to Yeh
  v_res := regexp_replace(v_res, 'ى', 'ي', 'g');
  -- Normalize Teh Marbuta to Heh
  v_res := regexp_replace(v_res, 'ة', 'ه', 'g');
  -- Collapse multiple whitespace characters into single space
  v_res := regexp_replace(v_res, '\s+', ' ', 'g');
  v_res := trim(v_res);

  IF length(v_res) = 0 THEN
    RETURN NULL;
  END IF;

  RETURN v_res;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_profile_privilege_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF (OLD.role IS DISTINCT FROM NEW.role OR OLD.is_active IS DISTINCT FROM NEW.is_active) THEN
    -- Only service_role or validated super_admin can change role / activation
    IF current_user <> 'service_role' AND NOT public.is_admin() THEN
      RAISE EXCEPTION 'Privilege escalation blocked: non-admin users cannot alter profile role or is_active.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
